<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref, watch } from 'vue'
import { ChevronLeft, ChevronRight, Minus, Plus, RotateCcw, X } from 'lucide-vue-next'
import Modal from './Modal.vue'
import type { Attachment } from '../types'
const props=defineProps<{images:Attachment[];initial:number;open:boolean}>();const emit=defineEmits<{close:[]}>();const index=ref(0),zoom=ref(1),dialog=ref<HTMLElement>();const current=computed(()=>props.images[index.value])
watch(()=>[props.open,props.initial],()=>{index.value=props.initial;zoom.value=1})
function move(delta:number){index.value=(index.value+delta+props.images.length)%props.images.length;zoom.value=1}
function key(event:KeyboardEvent){if(!props.open)return;if(event.key==='ArrowLeft'){event.preventDefault();move(-1)}if(event.key==='ArrowRight'){event.preventDefault();move(1)}if(event.key==='+'||event.key==='='){event.preventDefault();zoom.value=Math.min(4,zoom.value+.25)}if(event.key==='-'){event.preventDefault();zoom.value=Math.max(.5,zoom.value-.25)}if(event.key==='0'){event.preventDefault();zoom.value=1}}
onMounted(()=>window.addEventListener('keydown',key));onUnmounted(()=>window.removeEventListener('keydown',key))
</script>
<template><Modal :open="open" :title="current?.filename||'现场图片'" wide @close="emit('close')"><div ref="dialog" class="lightbox"><div class="lightbox-toolbar"><span>{{index+1}} / {{images.length}}</span><button class="icon-button" aria-label="缩小图片" @click="zoom=Math.max(.5,zoom-.25)"><Minus :size="18"/></button><span>{{Math.round(zoom*100)}}%</span><button class="icon-button" aria-label="放大图片" @click="zoom=Math.min(4,zoom+.25)"><Plus :size="18"/></button><button class="icon-button" aria-label="还原图片尺寸" @click="zoom=1"><RotateCcw :size="16"/></button><a v-if="current" class="text-button" :href="`/api/attachments/${current.id}`" :download="current.filename">下载原图</a></div><div class="lightbox-stage"><button v-if="images.length>1" class="lightbox-prev" aria-label="上一张图片" @click="move(-1)"><ChevronLeft/></button><div class="lightbox-scroll"><img v-if="current" :src="current.url||`/api/attachments/${current.id}`" :alt="current.filename" :style="{width:`${zoom*100}%`,maxWidth:'none'}"/></div><button v-if="images.length>1" class="lightbox-next" aria-label="下一张图片" @click="move(1)"><ChevronRight/></button></div><div class="lightbox-thumbnails"><button v-for="(item,i) in images" :key="item.id" :class="{selected:index===i}" :aria-label="`查看第 ${i+1} 张图片`" @click="index=i;zoom=1"><img :src="item.thumb_url||item.url||`/api/attachments/${item.id}`" :alt="item.filename"/></button></div><p class="input-hint">← → 切换 · + − 缩放 · 0 还原 · Esc 关闭；放大后可滚动查看。</p></div></Modal></template>
